def defined_symbols(obj, env):
    dump = subprocess.run([str(V.VC / "bin" / "dumpbin.exe"), "/symbols", "/headers", str(obj)],
                          capture_output=True, text=True, env=env).stdout
    # VC7.1 prints COMDAT selection in each static section symbol's auxiliary
    # record. Selection 1 is still a strong definition (no duplicates); inline
    # functions normally use selection 2 (pick any). The section headers do
    # not print the word "Communal", so that older check marked every inline
    # provider strong and misled dependency selection.
    communal = set(re.findall(
        r"^\S+\s+\S+\s+(SECT[0-9A-F]+)\s+notype\s+Static\s+\|[^\n]*\n"
        r"\s+Section length[^\n]*\bselection\s+[2-7]\b", dump, re.M))
    return [(name, "comdat" if sect in communal else "strong")
            for sect, name in SYM.findall(dump)]


